
(async()=>{
const r=document.getElementById('br-encounters'),$=s=>r.querySelector(s),c=$('canvas'),g=c.getContext('2d'),action=$('.be-action'),exit=$('.be-exit');
const data={"images": {"court": "data:image/webp;base64,", "clarth_warden_sw": "data:image/png;base64,", "bloodridge_chief_sw": "data:image/png;base64,", "blood_rot_skirmisher_se": "data:image/png;base64,", "clarth_skirmisher_sw": "data:image/png;base64,", "blood_rot_warden_se": "data:image/png;base64,"}, "frames": {"clarth_warden_sw": {"w": 188, "ax": 86.0, "h": 180, "ay": 152}, "bloodridge_chief_sw": {"w": 192, "ax": 94.5, "h": 256, "ay": 224}, "blood_rot_skirmisher_se": {"w": 160, "ax": 83.0, "h": 168, "ay": 140}, "clarth_skirmisher_sw": {"w": 140, "ax": 63.0, "h": 160, "ay": 132}, "blood_rot_warden_se": {"w": 160, "ax": 81.0, "h": 188, "ay": 157}}},im={};await Promise.all(Object.entries(data.images).map(async([k,src])=>{const a=new Image();a.src=src;await a.decode();im[k]=a}));
const scenes=[{name:'Outer court',line:'Clear the guards before your squad can move on.',exit:'UP THE BURIAL STEPS',next:'Burial steps',scale:1,x:0,y:0},{name:'Burial steps',line:'Another group holds the approach to the chief.',exit:'ENTER THE CHIEF’S COURT',next:'Chief’s court',scale:1.15,x:-160,y:-32},{name:'Chief’s court',line:'The route ends here. Face the Bloodridge chief.',exit:'',next:'',scale:1.07,x:-38,y:-12}];
let stage=0,phase='fight',p=0,raf=0,disposed=false;const ease=t=>t*t*(3-2*t),reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function background(s){const v=scenes[s];g.drawImage(im.court,v.x,v.y,1200*v.scale,750*v.scale);if(s===1){g.fillStyle='#241c2c14';g.fillRect(0,0,1200,750)}}
function sprite(key,x,y,size=1,alpha=1,flip=false){const m=data.frames[key];g.save();g.globalAlpha*=alpha;g.fillStyle='#2019226b';g.beginPath();g.ellipse(x,y+1,28*size,8*size,0,0,Math.PI*2);g.fill();g.translate(x,y);if(flip)g.scale(-1,1);g.drawImage(im[key],-m.ax*size,-m.ay*size,m.w*size,m.h*size);g.restore()}
const ours=[['clarth_skirmisher_sw',270,452,.9],['clarth_warden_sw',375,487,1],['clarth_skirmisher_sw',265,551,1],['clarth_warden_sw',386,584,1.04]];
const guards=[['blood_rot_skirmisher_se',873,435,.9],['blood_rot_warden_se',766,485,1],['blood_rot_skirmisher_se',883,542,1],['blood_rot_warden_se',773,580,1.04]];
function group(list,opacity=1,travel=0){for(const [key,x,y,size]of list){const q=ease(travel);sprite(key,x+(907-x)*q,y+(181-y)*q,size*(1-q*.67),opacity*(1-q*.85),true)}}
function path(){g.save();g.beginPath();g.moveTo(530,505);g.bezierCurveTo(645,458,786,335,913,185);g.strokeStyle='#30232dd9';g.lineWidth=12;g.stroke();g.strokeStyle='#f4d99c';g.lineWidth=5;g.setLineDash([12,16]);g.stroke();g.setLineDash([]);g.fillStyle='#f4d99c';g.beginPath();g.moveTo(913,172);g.lineTo(899,197);g.lineTo(921,192);g.closePath();g.fill();g.restore()}
function paint(){
 g.imageSmoothingEnabled=false;g.clearRect(0,0,1200,750);
 const travelling=phase==='travel',q=travelling?ease(p):0;
 g.save();if(travelling){g.translate(600,375);g.scale(1+q*.95,1+q*.95);g.translate(-600-q*217,-375+q*118)}
 background(stage);
 if(phase==='clear'&&stage<2)path();
 group(ours,1,travelling?p:0);
 const enemyAlpha=phase==='victory'?1-ease(p):phase==='fight'?1:0;
 if(stage===2){sprite('bloodridge_chief_sw',806,468,1.45,enemyAlpha);sprite('blood_rot_warden_se',911,556,1,enemyAlpha,true)}else group(guards,enemyAlpha);
 g.restore();
 if(travelling&&p>.58){g.globalAlpha=ease((p-.58)/.42);background(stage+1);group(ours);if(stage+1===2){sprite('bloodridge_chief_sw',806,468,1.45);sprite('blood_rot_warden_se',911,556,1,1,true)}else group(guards);g.globalAlpha=1}
 const shade=g.createLinearGradient(0,565,0,750);shade.addColorStop(0,'#21192300');shade.addColorStop(1,'#211923b3');g.fillStyle=shade;g.fillRect(0,565,1200,185);
}
function ui(){
 const scene=scenes[stage],busy=['victory','travel'].includes(phase),clear=phase==='clear';action.disabled=busy;$('.be-reset').disabled=busy;
 $('.be-kicker').textContent='ENCOUNTER 0'+(stage+1);$('h3').textContent=scene.name;
 $('.be-side.be-theirs').textContent=stage===2?'BLOODRIDGE CHIEF':'BLOODRIDGE GUARDS';$('.be-theirs').hidden=phase!=='fight';$('.be-ours').hidden=phase==='travel';$('.be-location').hidden=phase!=='fight';
 $('.be-victory').hidden=!(phase==='victory'||clear);$('.be-victory strong').textContent=stage===2?'The chief’s court is yours.':stage===1?'The steps are secured.':'The court is yours.';$('.be-victory small').textContent=stage===2?'End of this route preview.':'Your squad can move forward.';
 exit.hidden=!(clear&&stage<2);exit.innerHTML='<span>↑</span> '+scene.exit;$('.be-travel').hidden=phase!=='travel';$('.be-travel strong').textContent='Moving to '+scene.next;
 action.textContent=busy?(phase==='victory'?'Area clearing…':'Advancing…'):clear?(stage===2?'Replay route':'Advance to '+scene.next):'Preview victory';
 $('.be-phase').textContent=phase==='fight'?'1 · ENCOUNTER':phase==='victory'?'2 · VICTORY':clear?'2 · WAY FORWARD OPEN':'3 · ADVANCE';
 $('.be-copy p').textContent=phase==='fight'?scene.line:phase==='victory'?'The guards are cleared. Your squad holds this area.':phase==='travel'?'Stay in the world. Move through the cleared exit.':stage===2?'Route complete. Replay to judge the full sequence.':'Follow the highlighted stairs into the next encounter.';
 r.querySelectorAll('.be-route li').forEach((el,i)=>{el.classList.toggle('cleared',i<stage||i===stage&&clear);if(i===stage)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});
}
function save(){window.openai?.setWidgetState?.({modelContent:{proposal:'2.5D encounter, victory, advance',stage:stage+1,phase},privateContent:{encounterVersion:1,stage,phase}}).catch(()=>{})}
function animate(kind,ms){phase=kind;p=0;ui();const start=performance.now();function tick(now){if(disposed)return;p=reduced()?1:Math.min(1,(now-start)/ms);paint();if(p<1)raf=requestAnimationFrame(tick);else{if(kind==='travel'){stage++;phase='fight'}else phase='clear';p=0;ui();paint();save()}}raf=requestAnimationFrame(tick)}
function reset(){cancelAnimationFrame(raf);stage=0;phase='fight';p=0;ui();paint();save()}
function act(){if(phase==='fight')animate('victory',1000);else if(phase==='clear'){if(stage===2)reset();else animate('travel',3200)}}
action.addEventListener('click',act);exit.addEventListener('click',act);$('.be-reset').addEventListener('click',reset);
function restore(state){const saved=state?.privateContent;if(saved?.encounterVersion!==1)return;cancelAnimationFrame(raf);stage=Math.max(0,Math.min(2,saved.stage|0));phase=saved.phase==='clear'?'clear':'fight';p=0;ui();paint()}
ui();paint();restore(window.openai?.widgetState);window.addEventListener('openai:set_globals',e=>restore(e.detail?.globals?.widgetState));window.addEventListener('pagehide',()=>{disposed=true;cancelAnimationFrame(raf)},{once:true});
})().catch(()=>{document.querySelector('#br-encounters .be-copy p').textContent='Artwork did not load. Reload to retry.'});
